/* Convergence Monte Carlo : estimation courante + bande d'erreur ±1,96 s.e. en 1/√b */
(function () {
  var svg = document.getElementById("mc-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  // Chocs déterministes (LCG + Box-Muller, seed fixe)
  function makeNormals(count, seed){
    var out=[];
    function rnd(){ seed=(1103515245*seed+12345)&0x7fffffff; return seed/0x7fffffff; }
    for (var i=0;i<count;i++){
      var u1=Math.max(rnd(),1e-9), u2=rnd();
      out.push(Math.sqrt(-2*Math.log(u1))*Math.cos(2*Math.PI*u2));
    }
    return out;
  }
  var TARGET=100, ANTI=0.755, MAXB=5000;
  var Z = makeNormals(MAXB, 24681012);

  function draw(){
    var b=Math.round(v("mc-b")), sigma=v("mc-sigma"), anti=document.getElementById("mc-anti").checked;
    setT("mc-b-o", b.toString()); setT("mc-sigma-o", sigma.toFixed(0));

    // estimation courante = moyenne des g(Xi) = TARGET + sigma*Z (running mean)
    var run=0, est=[];
    for (var i=0;i<b;i++){ run += TARGET + sigma*Z[i]; est.push(run/(i+1)); }
    var final = est[b-1];
    var se = sigma/Math.sqrt(b);
    setT("mc-est", final.toFixed(2)); setT("mc-se", se.toFixed(3));
    var antiOut=document.getElementById("mc-anti-out");
    if (anti){ antiOut.style.display=""; setT("mc-se-a", (se*ANTI).toFixed(3)); } else { antiOut.style.display="none"; }

    // échelle : x logarithmique de 1 à b, y autour de TARGET
    var W=520,H=300,L=46,R=16,T0=16,B=34, pw=W-L-R, ph=H-T0-B;
    var i0=5; // on démarre le tracé à la 5e réplication (bande initiale sinon énorme)
    var logmin=Math.log(i0), logmax=Math.log(Math.max(b,i0+1));
    function px(i){ return L + (Math.log(i)-logmin)/(logmax-logmin)*pw; }
    var hw0=1.96*sigma/Math.sqrt(i0); // demi-largeur max (au début)
    var yspan=Math.max(hw0*1.1, sigma*0.5);
    function py(val){ return T0 + (1-((val-TARGET)+yspan)/(2*yspan))*ph; }

    var g="";
    // bande d'erreur théorique ±1,96 s.e.(i)
    function band(factor, fill, op){
      var up="", lo=[];
      for (var i=i0;i<=b;i+=Math.max(1,Math.round((b-i0)/160))){
        var hw=1.96*sigma/Math.sqrt(i)*factor;
        up += (up===""?"M ":" L ")+px(i).toFixed(1)+","+py(TARGET+hw).toFixed(1);
        lo.push([px(i).toFixed(1), py(TARGET-hw).toFixed(1)]);
      }
      for (var k=lo.length-1;k>=0;k--){ up += " L "+lo[k][0]+","+lo[k][1]; }
      up += " Z";
      return '<path d="'+up+'" fill="'+fill+'" opacity="'+op+'"/>';
    }
    g += band(1, "var(--teal)", 0.13);
    if (anti) g += band(ANTI, "var(--gold)", 0.20);
    // ligne vraie valeur
    g += '<line x1="'+L+'" y1="'+py(TARGET).toFixed(1)+'" x2="'+(L+pw)+'" y2="'+py(TARGET).toFixed(1)+'" stroke="var(--crimson)" stroke-width="1.4" stroke-dasharray="5 4"/>';
    // trajectoire de l'estimation
    var d="";
    for (i=i0;i<b;i+=Math.max(1,Math.round(b/260))){ d+=(d===""?"M ":" L ")+px(i).toFixed(1)+","+py(est[i-1]).toFixed(1); }
    d+=" L "+px(b).toFixed(1)+","+py(final).toFixed(1);
    g += '<path d="'+d+'" fill="none" stroke="var(--teal)" stroke-width="2"/>';
    // axes
    g += '<line class="axis" x1="'+L+'" y1="'+(T0+ph)+'" x2="'+(L+pw)+'" y2="'+(T0+ph)+'"/>';
    g += '<line class="axis" x1="'+L+'" y1="'+T0+'" x2="'+L+'" y2="'+(T0+ph)+'"/>';
    // libellés
    var xlab = al()==="en"?"replications b (log)":(al()==="nl"?"replicaties b (log)":"réplications b (log)");
    var vlab = al()==="en"?"true value":(al()==="nl"?"echte waarde":"vraie valeur");
    g += '<text class="lab" x="'+(L+pw)+'" y="'+(T0+ph+16)+'" text-anchor="end">'+xlab+'</text>';
    g += '<text class="tick" x="'+(L+pw)+'" y="'+(py(TARGET)-4).toFixed(1)+'" text-anchor="end" fill="var(--crimson)">'+vlab+'</text>';
    svg.innerHTML=g;
  }
  ["mc-b","mc-sigma"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  var chk=document.getElementById("mc-anti"); if(chk) chk.addEventListener("change", draw);
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
